const userText =
  ($json.chatInput || $json.message || $json.text || "").trim();

// capture all possible identifiers (varies by n8n versions)
const ids = {
  sessionId: $json.sessionId,
  chatId: $json.chatId,
  conversationId: $json.conversationId,
  threadId: $json.threadId,
};

// pick the most stable one available (priority order)
const sessionId =
  $json.conversationId ||
  $json.chatId ||
  $json.threadId ||
  $json.sessionId ||
  "default-session";

const globalData = $getWorkflowStaticData('global');
if (!globalData.sessions) globalData.sessions = {};
if (!globalData.sessions[sessionId]) globalData.sessions[sessionId] = { stage: "need_category" };

return [{
  sessionId,
  userText,
  state: globalData.sessions[sessionId],
  ids // debug info
}];

const userText = ($json.userText || "").trim();
const sessionId = $json.sessionId;
const state = $json.state || { stage: "need_category" };

const norm = userText.toLowerCase();

let action = "unknown";

// Restart always works
if (/^\s*restart\s*$/i.test(userText)) {
  action = "restart";
  state.stage = "need_category";
  return [{ sessionId, userText, action, state }];
}

// 1️⃣ If waiting for category
if (state.stage === "need_category") {
  if (norm.includes("business")) {
    state.category = "Business & Finance";
    state.stage = "need_topics";
    action = "got_category";
  } else if (norm.includes("entertainment") || norm.includes("arts")) {
    state.category = "Entertainment & Arts";
    state.stage = "need_topics";
    action = "got_category";
  } else if (norm.includes("environment") || norm.includes("nature")) {
    state.category = "Environment & Nature";
    state.stage = "need_topics";
    action = "got_category";
  } else if (norm.includes("science") || norm.includes("tech")) {
    state.category = "Science & Technology";
    state.stage = "need_topics";
    action = "got_category";
  } else {
    action = "ask_category";
  }
}

// 2️⃣ If we already generated topics and are waiting for confirm
else if (state.stage === "await_confirm") {
  const match = userText.match(/^\s*(confirm|pick|choose)\s*([1-5])\s*$/i);

  if (match) {
    state.choice = parseInt(match[2], 10);
    action = "confirm_topic";
  } else {
    action = "ask_confirm";
  }
}

// 3️⃣ If topic already confirmed
else if (state.stage === "topic_confirmed") {
  action = "already_confirmed";
}

// Fallback
else {
  action = "ask_category";
  state.stage = "need_category";
}

return [{ sessionId, userText, action, state }];

// 1) Pull the raw text from the AI Agent wrapper
const rawText =
  $json?.response?.generations?.[0]?.[0]?.text
  ?? $json?.output
  ?? null;

if (!rawText || typeof rawText !== "string") {
  return [{
    error: "Could not find AI text output to parse",
    debug: $json
  }];
}

// 2) Parse the JSON text
let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  return [{
    error: "AI text was not valid JSON",
    debug_rawText: rawText.slice(0, 1000)
  }];
}

// 3) Determine which category the user chose (from Stage router state)
const sessionId = $node["Get session state"].json.sessionId;
const chosenCategory = $node["Stage router"].json.state?.category;

// 4) Your AI returned a 4-category batch. Extract the matching category block.
let categoryBlock = null;

if (parsed.type === "daily_topic_research" && Array.isArray(parsed.categories)) {
  categoryBlock = parsed.categories.find(c => c.category === chosenCategory);
} else {
  // fallback: if it ever returns single-category format
  categoryBlock = parsed;
}

if (!categoryBlock) {
  return [{
    error: "Could not find chosen category in AI output",
    chosenCategory,
    debug_parsedKeys: Object.keys(parsed)
  }];
}

// 5) Save topics to workflow static data
const globalData = $getWorkflowStaticData('global');
if (!globalData.sessions) globalData.sessions = {};
if (!globalData.sessions[sessionId]) globalData.sessions[sessionId] = { stage: "need_category" };

globalData.sessions[sessionId].stage = "await_confirm";
globalData.sessions[sessionId].category = chosenCategory;

// Normalize field names to what your chat response expects
const recommended = categoryBlock.recommended_topic ?? categoryBlock.recommended;
const runnerUps = categoryBlock.runner_up_topics ?? categoryBlock.runner_ups;

globalData.sessions[sessionId].topics = {
  recommended,
  runner_ups: runnerUps
};

// 6) Output clean data for Respond to Chat
return [{
  sessionId,
  category: chosenCategory,
  recommended,
  runner_ups: runnerUps
}];

