parameters.jsCode:
const sessionId = $json.sessionId;
const choice = $json.state.choice; // from Stage router parsing "CONFIRM 1-5"

const globalData = $getWorkflowStaticData('global');
const session = globalData.sessions?.[sessionId];

if (!session || !session.topics) {
  return [{
    error: "No topic suggestions found for this session. Type RESTART and choose a category again."
  }];
}

const recommended = session.topics.recommended;
const runnerUps = session.topics.runner_ups;

let selected;
if (choice === 1) {
  selected = recommended;
} else if (choice >= 2 && choice <= 5) {
  selected = runnerUps[choice - 2];
} else {
  return [{ error: "Invalid choice. Reply CONFIRM 1 (or 2–5)." }];
}

// Persist selection
session.stage = "topic_confirmed";
session.selected = { choice, ...selected };

return [{
  sessionId,
  category: session.category,
  selected: session.selected
}];

